import { Component, createEffect, createSignal, For, Show } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { isMobile } from "#core/ui-next/services/view-experience.js";

import {
	getOpFlagString,
	getTraitIcon,
	SyncItemProps,
	SyncretismCard,
	SyncretismScreenModel,
} from "./syncretism-screen-model.js";

//#region main card
export const SyncCard: Component<SyncretismCard> = (props) => {
	const model = SyncretismScreenModel.get();

	return (
		<div
			style={props.style}
			class={props.class}
		>
			<Activatable
				onActivate={() => model.onCardClick(props)}
				class={"mx-1 relative grow syncretism-card"}
				audio={{
					group: "audio-base",
					onPress: "data-audio-hero-press",
					onActivate: "data-audio-hero-press",
					onFocus: "data-audio-hero-focus",
				}}
				hotkeyAction="accept"
			>
				<SyncCardBG {...props} />
				<div class={"relative flex flex-col justify-start flex-auto px-2 pb-1 pt-1"}>
					<SyncCardHeader {...props} />
					<div class="flex flex-col flex-auto mx-1">
						<For each={props.itemsAvailable}>
							{(item) => (
								<SyncItemExpanded
									class="flex-row flex m-1 p-1"
									title={item.name}
									icon={item.icon}
									description={item.description}
									addInfo1={item.addInfo1}
									addInfo2={item.addInfo2}
								/>
							)}
						</For>
					</div>
				</div>
				<div class={"syncretism-hover absolute -inset-2"} />
			</Activatable>
		</div>
	);
};

const SyncCardBG: Component<SyncretismCard> = (props) => {
	return (
		<div class={"size-full absolute"}>
			<div
				class={"size-full absolute"}
				data-name="sync-card-bg"
				style={{
					"background-image": `url('${props.bgImage}')`,
					"background-size": "cover",
					"background-position-x": "50%",
					opacity: "0.80",
				}}
			/>
			<div
				class={"size-full absolute syncretism-card-bg-gradient"}
				data-name="sync-card-bg"
			/>
			<div class={"w-full h-24 absolute syncretism-card-title-gradient"} />

			<div
				class={"syncretism-card-hover absolute inset-0 opacity-0"}
				data-name="sync-card-hover"
			/>
		</div>
	);
};

const SyncCardHeader: Component<SyncretismCard> = (props) => {
	return (
		<div class="flex flex-row px-2 pt-1">
			<Icon
				class={`${isMobile() ? "size-14" : "size-12"} self-center`}
				name={props.civIcon}
				isUrl={true}
			/>
			<div class="flex flex-row flex-auto justify-start px-1 pt-1 pb-2">
				<div class="p-1">
					<L10n.Stylize
						class="fxs-header text-shadow-subtle font-bold text-lg font-title uppercase tracking-100"
						text={props.civ}
					/>
					<div class="text-body">{Locale.compose(getOpFlagString(props.flagType))}</div>
				</div>
			</div>
			<Icon
				class={`${isMobile() ? "size-10 mx-1" : "size-8"} self-center`}
				name={`url('blp:${getTraitIcon(props.traits[0]) ?? ""}')`}
				isUrl={false}
			/>
			<Icon
				class={`${isMobile() ? "size-10 mx-1" : "size-8"} self-center`}
				name={`url('blp:${getTraitIcon(props.traits[1]) ?? ""}')`}
				isUrl={false}
			/>
		</div>
	);
};
export const SyncItemExpanded: Component<SyncItemProps> = (props) => {
	const [lockedBG, setLockedBG] = createSignal<string>("flex-row mt-1 img-ticket-solid-shadow-container");
	createEffect(() => {
		if (props.addInfo2)
			if (props.addInfo2 != "") {
				setLockedBG("flex-row mt-1 sync-locked-ticket-bg");
			}
	});

	return (
		<div class={lockedBG()}>
			<div class={props.class}>
				<div class="flex flex-col relative items-center justify-center">
					<Icon
						class="size-12 self-center mr-2"
						name={props.icon ?? ""}
						isUrl={true}
					/>
					<Show when={props.addInfo2}>
						<Icon
							class={"-mt-5 size-9 self-center"}
							name={`url('blp:icon_lock')`}
							isUrl={false}
						/>
					</Show>
				</div>
				<div class="flex flex-auto justify-center flex-col ml-3">
					<div class="font-title uppercase text-secondary pr-2 pb-1">
						<L10n.Stylize text={props.title} />
					</div>
					<div class="text-sm pb-1">
						<L10n.Stylize text={props.description} />
					</div>
				</div>
			</div>
			<SyncItemUpgrade {...props} />
			<SyncItemRequires {...props} />
		</div>
	);
};
export const SyncItemUpgrade: Component<SyncItemProps> = (props) => {
	return (
		<Show when={props.addInfo1 != "" && props.addInfo1}>
			<div class="mx-2 mt-2 flex flex-row bg-accent-6 ">
				<Icon
					class={"size-5 self-center mx-1"}
					name={`url('blp:buildicon_warning')`}
					isUrl={false}
				/>
				<L10n.Stylize
					class="text-info font-bold text-sm uppercase flex text-center px-4 pb-1 pt-1"
					text={props.addInfo1 ?? ""}
				/>
			</div>
		</Show>
	);
};
export const SyncItemRequires: Component<SyncItemProps> = (props) => {
	return (
		<Show when={props.addInfo2 != "" && props.addInfo2}>
			<div class="mx-2 mt-2 flex flex-row bg-accent-6 ">
				<Icon
					class={"size-5 self-center mx-1"}
					name={`url('blp:buildicon_warning')`}
					isUrl={false}
				/>
				<L10n.Stylize
					class="text-accent-1 font-bold text-sm uppercase flex px-4 pb-1 pt-1"
					text={props.addInfo2 ?? ""}
				/>
			</div>
		</Show>
	);
};
//#region sync preview card
export const SyncretismPreviewCard: Component<SyncretismCard> = (props) => {
	return (
		<div
			style={props.style}
			class={props.class}
		>
			<div class={"mx-2 relative grow"}>
				<div
					class={`size-full absolute ${props.isSyncretized ? "" : "syncretism-card-lock"}`}
					data-name="sync-card-bg"
					style={{
						"background-image": `url('${props.bgImage}')`,
						"background-size": "cover",
						"background-position-x": "50%",
						opacity: "0.80",
					}}
				/>
				<div
					class={`size-full absolute syncretism-card-bg-gradient ${props.isSyncretized ? "border border-tertiary" : ""}`}
					data-name="sync-card-bg"
				/>
				<div class={"w-full h-24 absolute syncretism-card-title-gradient"} />

				<div class={"relative flex flex-col justify-start flex-auto px-2 pb-1 pt-1"}>
					<div class="flex flex-row pr-2 pt-1">
						<Tooltip.Text text={Locale.stylize("LOC_UI_SYNCRETISM_PREVIEW_ONLY")}>
							<div class="syncretism-card-bottom-lock flex items-center">
								<Show when={!props.isSyncretized}>
									<Icon
										class={"size-14 self-center"}
										name={`url('blp:icon_lock')`}
										isUrl={false}
									/>
								</Show>
							</div>
						</Tooltip.Text>
						<Icon
							class={`${isMobile() ? "size-14" : "size-12"} self-center`}
							name={props.civIcon}
							isUrl={true}
						/>
						<div class="flex flex-row flex-auto justify-start px-1 pt-1 pb-2">
							<div class="p-1">
								<L10n.Stylize
									class={`text-shadow-subtle font-bold text-lg font-title uppercase tracking-100 ${props.isSyncretized ? "fxs-header" : ""}`}
									text={props.civ}
								/>
								<div class="text-body">{Locale.compose(getOpFlagString(props.flagType))}</div>
							</div>
						</div>
						<Icon
							class={`${isMobile() ? "size-10 mx-1" : "size-8"} self-center ${props.isSyncretized ? "" : "syncretism-card-lock"}`}
							name={`url('blp:${getTraitIcon(props.traits[0]) ?? ""}')`}
							isUrl={false}
						/>
						<Icon
							class={`${isMobile() ? "size-10 mx-1" : "size-8"} self-center ${props.isSyncretized ? "" : "syncretism-card-lock"}`}
							name={`url('blp:${getTraitIcon(props.traits[1]) ?? ""}')`}
							isUrl={false}
						/>
					</div>
					<div class="flex flex-col flex-auto mx-1">
						<For each={props.itemsAvailable}>
							{(item) => (
								<SyncPreviewItem
									class="flex-row flex m-1 p-1"
									title={item.name}
									icon={item.icon}
									description={item.description}
									addInfo1={item.addInfo1}
									addInfo2={item.addInfo2}
								/>
							)}
						</For>
					</div>
				</div>
			</div>
		</div>
	);
};

export const SyncPreviewItem: Component<SyncItemProps> = (props) => {
	const [lockedBG, setLockedBG] = createSignal<string>("flex-row mt-1 img-ticket-solid-shadow-container");

	createEffect(() => {
		if (props.addInfo2)
			if (props.addInfo2 != "") {
				setLockedBG("flex-row mt-1 sync-locked-ticket-bg");
			}
	});
	return (
		<div class={lockedBG()}>
			<div class={props.class}>
				<Icon
					class="size-12 self-center mr-2"
					name={props.icon ?? ""}
					isUrl={true}
				/>
				<div class="flex flex-auto justify-center flex-col">
					<div class="font-title text-accent-1 pr-2 pb-1">
						<L10n.Stylize text={props.title} />
					</div>
					<div class="text-sm pb-1">
						<L10n.Stylize text={props.description} />
					</div>
				</div>
			</div>
			<SyncItemRequires {...props} />
			<SyncItemUpgrade {...props} />
		</div>
	);
};
